import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../../../data/models/saving.dart';
import '../../../data/repositories/group_repository.dart';
import '../../widgets/app_drawer.dart';
class SavingsScreen extends StatelessWidget{const SavingsScreen({super.key});@override Widget build(BuildContext context){final repo=context.read<GroupRepository>();return Scaffold(appBar:AppBar(title:const Text('Savings')),drawer:const AppDrawer(),floatingActionButton:FloatingActionButton(onPressed:()=>_add(context,repo),child:const Icon(Icons.add)),body:ListView(padding:const EdgeInsets.all(16),children:[const Text('Savings History',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold)),StreamBuilder(stream:repo.savings(),builder:(c,s)=>Column(children:(s.data??[]).map((x)=>Card(child:ListTile(title:Text(x.toString()),subtitle:Text('Digital record')))).toList()))]));} void _add(BuildContext context,GroupRepository repo){final member=TextEditingController();final amount=TextEditingController();final type=TextEditingController();showDialog(context:context,builder:(_)=>AlertDialog(title:const Text('Record Savings'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:member,decoration:const InputDecoration(labelText:'Member / Description / Agenda')),TextField(controller:amount,decoration:const InputDecoration(labelText:'Amount / Decisions'),keyboardType:TextInputType.number),TextField(controller:type,decoration:const InputDecoration(labelText:'Type'))]),actions:[FilledButton(onPressed:(){repo.addSaving(Saving(id:'',memberId:member.text,amount:double.tryParse(amount.text)??0,date:DateTime.now()));Navigator.pop(context);},child:const Text('Save'))]));}}
